<template><div class="page"><h2 class="page-title">周度消费预测</h2><el-alert title="预测用于估计正常消费趋势，不代表实际消费承诺；计划外大额支出可能造成较大误差。" type="warning" :closable="false"/><div class="card section"><div class="actions"><el-select v-model="goalId" placeholder="选择储蓄目标"><el-option v-for="g in goals" :key="g.id" :label="`目标 ${formatMoney(g.target_savings_minor)}`" :value="g.id"/></el-select><el-button type="primary" :loading="loading" @click="load">生成预测</el-button></div><EChart v-if="totals.length" :option="chart"/><EmptyGuide v-else description="请选择已有目标并先设置分类预算约束" action="/goals"/></div><div v-if="items.length" class="card section"><h3>分类正常消费参考</h3><p>餐饮：中等置信参考；购物：低置信参考。</p><el-table :data="references"><el-table-column prop="target_key" label="类别"/><el-table-column label="周参考"><template #default="s">{{formatMoney(s.row.predicted_minor)}}</template></el-table-column><el-table-column label="说明"><template #default="s">{{s.row.target_key==='food'?'中等置信参考':s.row.target_key==='shopping'?'低置信参考':'历史结构参考'}}</template></el-table-column></el-table></div></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue'
const goals=ref([]),goalId=ref(),items=ref([]),loading=ref(false);onMounted(async()=>goals.value=(await api.get('/goals')).items)
async function load(){loading.value=true;try{items.value=(await api.get(`/forecasts/weekly?goal_id=${goalId.value}`)).items}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
const totals=computed(()=>items.value.filter(x=>x.target_key==='total'));const references=computed(()=>{const first=new Map();items.value.filter(x=>x.target_key!=='total').forEach(x=>first.has(x.target_key)||first.set(x.target_key,x));return [...first.values()]})
const chart=computed(()=>({tooltip:{trigger:'axis'},legend:{},xAxis:{type:'category',data:totals.value.map(x=>x.week_start)},yAxis:{type:'value'},series:[{name:'预测',type:'line',data:totals.value.map(x=>x.predicted_minor),color:'#2b9a72'},{name:'80%下界',type:'line',lineStyle:{type:'dashed'},data:totals.value.map(x=>x.lower_minor)},{name:'80%上界',type:'line',lineStyle:{type:'dashed'},data:totals.value.map(x=>x.upper_minor)}]}))
</script>
